R=[
("जड़ी-बूटियों वाला बीन डिप",
 "किसे नाश्ता चाहिए? यह किफ़ायती छोटा-सा व्यंजन बस कुछ सामग्रियों से बनता है और मिनटों में तैयार हो जाता है। यह प्रोटीन से भरपूर और कम वसा वाला है, इसलिए मधुमेह वाले लोगों के लिए यह एक बढ़िया और हृदय के लिए अच्छा नाश्ता है। ताज़ी जड़ी-बूटियाँ इस व्यंजन का स्वाद बढ़ाती हैं, लेकिन वे ज़रूरी नहीं हैं। सूखी जड़ी-बूटियाँ, या फिर अजवाइन की पत्तियाँ या हरे प्याज़ (स्कैलियन) का हरा हिस्सा भी बिल्कुल सही विकल्प हैं। दरअसल, इन्हें इस्तेमाल करने का यह बहुत अच्छा तरीका है ताकि ये बेकार न जाएँ!",
 "10","2 बड़े चम्मच",
 ["1/4 छोटा चम्मच पिसी काली मिर्च","1/4 कप ताज़ी जड़ी-बूटियाँ (अजमोद, चाइव्स, तुलसी, सोआ या पुदीने का कोई भी मिश्रण, शेफ़ टिप देखें) (कटी हुई)","1 लहसुन की कली (बारीक कटी हुई)","1/4 कप पानी","1 1/2 कप कम सोडियम वाली डिब्बाबंद फलियाँ (जैसे पिंटो, कैनेलिनी या ग्रेट नॉर्दर्न बीन्स) (छानकर और धोकर)"],
 ["सभी सामग्री को एक कटोरे में डालें और कांटे या आलू मैशर से मसलकर मिला लें।","कटी हुई कच्ची सब्ज़ियों, साबुत अनाज वाले टॉर्टिला चिप्स या क्रैकर्स के साथ परोसें, या सैंडविच या रैप की भरावन के रूप में इस्तेमाल करें।"]),
("सूरजमुखी के बीज का बटर",
 "सूरजमुखी के बीज के बटर की पोषण संबंधी जानकारी",
 "1","2 बड़े चम्मच",
 ["2 बड़े चम्मच सूरजमुखी के बीज का बटर"],[]),
("आसान ब्रोकली और झींगा स्टर-फ्राई",
 "30 मिनट से भी कम समय में सेहतमंद और स्वादिष्ट रात का खाना तैयार कर लेने से ज़्यादा संतोषजनक कुछ नहीं! इस रेसिपी में ब्रोकली के फूल इस्तेमाल हुए हैं, लेकिन आप अपने पास मौजूद किसी भी बिना स्टार्च वाली सब्ज़ी (जैसे फूलगोभी, ज़ुकीनी, स्नो पी या पत्तागोभी) के 3 कप ले सकते हैं। पूरी थाली के लिए इसे ब्राउन राइस या किसी और साबुत अनाज के साथ परोसें।",
 "4","1 1/4 कप",
 ["1/4 कप कम सोडियम वाला वेजिटेबल ब्रॉथ","2 बड़े चम्मच राइस विनेगर","1 1/2 बड़े चम्मच कम सोडियम वाला सोया सॉस","1 बड़ा चम्मच कॉर्नस्टार्च","1 छोटा चम्मच पिसी अदरक","1/2 छोटा चम्मच श्रीराचा","1/2 छोटा चम्मच ब्राउन शुगर का विकल्प","3 बड़े चम्मच ज़ैतून का तेल (बाँटकर इस्तेमाल करें)","1 लहसुन की कली (बारीक कटी हुई)","1 1/4 पाउंड झींगा (मध्यम आकार का, छिला हुआ, नस निकाली हुई और पूँछ कटी हुई)","3 कप ब्रोकली"],
 ["एक छोटे कटोरे में वेजिटेबल ब्रॉथ, राइस विनेगर, सोया सॉस, कॉर्नस्टार्च, अदरक, श्रीराचा और ब्राउन शुगर ब्लेंड को फेंटकर मिला लें।","एक बड़ी कड़ाही या वोक में 2 बड़े चम्मच ज़ैतून का तेल गरम करें। जब तेल में हल्की चमक आ जाए, तो लहसुन डालें और खुशबू आने तक पकाएँ (30 सेकंड)।","झींगा डालें और अपारदर्शी होने तक लगभग 4 मिनट पकाएँ। छेदों वाले चम्मच से झींगा निकालकर एक प्लेट में रख दें।","उसी कड़ाही में बचा हुआ 1 बड़ा चम्मच ज़ैतून का तेल गरम करें। ब्रोकली के फूल डालें और नरम होने तक लगभग 4 मिनट पकाएँ।","पके हुए झींगे को वापस कड़ाही में डालें और ब्रोकली के साथ मिलाने के लिए उछालकर चलाएँ। ब्रॉथ का मिश्रण झींगे और ब्रोकली पर डालें और उसे अच्छी तरह लपेटने के लिए चलाएँ। ब्रॉथ का मिश्रण थोड़ा गाढ़ा होने तक, लगभग 1 मिनट, पकाना जारी रखें।"]),
("छोले के साथ टूना सलाद",
 "छोले वाला यह टूना सलाद स्वाद और कुरकुरेपन से भरपूर है। इसे फैट-फ़्री सादा दही और लाइट मेयोनेज़ मिलाकर हल्का बनाया गया है - आप हैरान रह जाएँगे कि आपको स्वाद में कोई फ़र्क महसूस नहीं होता।",
 "7","1/2 कप",
 ["3 बड़े चम्मच सादा दही (फैट-फ़्री)","1/4 कप लाइट मेयोनेज़","1 बड़ा चम्मच नींबू का रस (1/2 मध्यम नींबू से)","1/2 बड़ी लाल शिमला मिर्च (छोटे टुकड़ों में कटी हुई)","2 डंठल अजवाइन (छोटे टुकड़ों में कटे हुए)","1/4 कप हरा प्याज़ (स्कैलियन) (बारीक कटा हुआ)","1 कप छोले (काबुली चने) (धोकर और छानकर)","2 पूरे टूना फ़्लेवरसील पाउच (प्रत्येक 6.4 औंस, पानी में)","1/4 छोटा चम्मच काली मिर्च"],
 ["एक छोटे कटोरे में दही, मेयोनेज़ और नींबू का रस फेंटकर मिला लें।","एक मध्यम कटोरे में बाकी सामग्री मिला लें। मेयोनेज़ का मिश्रण टूना पर डालें और अच्छी तरह मिलाएँ।","टूना सलाद को अपनी पसंद के अनुसार सलाद पत्ता, साबुत गेहूँ की ब्रेड या क्रैकर्स पर परोसें।"]),
("ब्रोकली के साथ खट्टे फलों वाला माही-माही पैकेट",
 "अगर आप नहीं जानते कि मछली बनाना कैसे शुरू करें, तो इस पैकेट जैसा कोई सरल और स्वादिष्ट तरीका आज़माएँ। यह नींबू, संतरे और सोआ के ताज़े स्वादों से भरपूर है। मछली को चर्मपत्र कागज़ (पार्चमेंट पेपर) की पोटली में बंद करने से वह भाप में बिल्कुल सही पकती है और खट्टे फलों और जड़ी-बूटियों का स्वाद उसमें रच-बस जाता है। अगर आपके पास पार्चमेंट पेपर नहीं है, तो एल्युमीनियम फ़ॉइल भी चलेगा। हमने माही-माही इस्तेमाल की है, लेकिन आप यह रेसिपी किसी भी मछली के फ़िलेट से बना सकते हैं।",
 "2","1 माही-माही फ़िलेट, 1 कप ब्रोकली",
 ["1/2 पूरे नींबू का रस (निचोड़ा हुआ)","1 बड़ा चम्मच ज़ैतून का तेल","1/4 छोटा चम्मच काली मिर्च","2 बड़े चम्मच कटा हुआ ताज़ा सोआ","1 पूरा नींबू (कटा हुआ)","1 संतरा (कटा हुआ)","2 (5 औंस) माही-माही फ़िलेट","1 ब्रोकली का गुच्छा (फूलों में कटा हुआ)"],
 ["ओवन को 425° F पर पहले से गरम करें। एक बेकिंग शीट पर पार्चमेंट पेपर के दो टुकड़े रखें।","एक छोटे कटोरे में नींबू का रस, ज़ैतून का तेल, काली मिर्च और सोआ फेंटकर मिला लें।","पार्चमेंट पेपर के बीच में नींबू और संतरे के कुछ टुकड़े रखें। मछली के फ़िलेट को संतरे और नींबू के टुकड़ों के ऊपर रखें। नींबू वाली चटनी मछली के फ़िलेट पर बराबर से डालें। मछली के ऊपर बचे हुए संतरे और नींबू के टुकड़े रखें। पार्चमेंट पेपर का ऊपरी हिस्सा मोड़ें, फिर किनारों को अंदर की ओर लपेटकर बंद पोटली बना लें।","पैकेट को बेकिंग शीट पर रखें और 25 मिनट या पकने तक बेक करें।","जब मछली बेक हो रही हो, तब ब्रोकली को 5-6 मिनट भाप में पकाएँ।","मछली का पैकेट भाप में पकी ब्रोकली के साथ परोसें। मछली का पैकेट खोलते समय सावधानी रखें, क्योंकि भाप गरम हो सकती है।"]),
("आधुनिक टूना नूडल कैसरोल",
 "यह रेसिपी इस बात का बढ़िया उदाहरण है कि आमतौर पर कार्ब्स और वसा से भरपूर व्यंजन को सब्ज़ियों से कैसे भरपूर बनाया जा सकता है।",
 "8","1 कप",
 ["1 नॉनस्टिक कुकिंग स्प्रे","12 औंस साबुत अनाज वाला पेन्ने, शेल्स या फ़ार्फ़ाले पास्ता","1 बड़ा चम्मच ज़ैतून का तेल","8 औंस सफ़ेद (बटन) मशरूम (कटे हुए)","1 छोटा प्याज़ (छोटे टुकड़ों में कटा हुआ)","5 औंस बेबी पालक","1/2 छोटा चम्मच बिना नमक वाला सर्व-उद्देशीय मसाला","3 बड़े चम्मच आटा","2 कप स्किम दूध","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","5 औंस पानी में पैक किया हुआ टूना (छानकर)","1/2 कप पारमेसन चीज़ (कसा हुआ)"],
 ["ओवन को 375 डिग्री F पर पहले से गरम करें। 9x13 इंच की बेकिंग डिश पर कुकिंग स्प्रे लगाएँ। एक तरफ़ रख दें।","पास्ता को पैकेट पर दिए निर्देशों के अनुसार, उसमें से दो मिनट कम पकाएँ (पास्ता थोड़ा कच्चा रहना चाहिए)।","जब पास्ता पक रहा हो, तब एक बड़े सॉते पैन में मध्यम-तेज़ आँच पर ज़ैतून का तेल डालें। प्याज़ और मशरूम डालें और प्याज़ पारदर्शी होने तक, लगभग 5 मिनट, भूनें।","पालक और बिना नमक वाला मसाला डालें और पालक के मुरझाकर नरम होने तक, लगभग 3 मिनट और भूनें।","एक छोटे कटोरे में आटा, दूध, नमक और पिसी काली मिर्च को तब तक फेंटें जब तक आटे की सारी गाँठें घुल न जाएँ। इसे सब्ज़ियों पर डालें और उबाल आने दें। टूना और पास्ता मिलाएँ और तैयार की हुई बेकिंग डिश में डाल दें।","कैसरोल के ऊपर पारमेसन चीज़ छिड़कें और 15 मिनट बेक करें।"]),
("भुनी सब्ज़ियों वाला ग्रेन बाउल, सियर की हुई तिलापिया और जड़ी-बूटियों वाली दही की चटनी के साथ",
 "यह संतुलित ग्रेन बाउल उच्च फ़ाइबर वाली क्विनोआ, भुनी हुई सब्ज़ियों और हृदय के लिए अच्छी तिलापिया के साथ एक संतोषजनक, मधुमेह के अनुकूल भोजन है। जड़ी-बूटियों वाली सरल दही की चटनी अतिरिक्त वसा या सोडियम के बिना स्वाद बढ़ाती है, जो इसे दोपहर या रात के खाने के लिए एक समझदारी भरा विकल्प बनाती है। यह DASH (उच्च रक्तचाप रोकने के लिए आहार संबंधी तरीके), कम वसा वाली और भूमध्यसागरीय रेसिपी है।",
 "4","1/2 कप क्विनोआ, 1/2 कप अरुगुला, 1 कप भुनी सब्ज़ियाँ, 4 औंस तिलापिया",
 ["3/4 कप क्विनोआ (सूखी)","2 कप शकरकंद (छिले और छोटे टुकड़ों में कटे हुए)","1 छोटी ज़ुकीनी (कटी हुई)","1 पूरी लाल शिमला मिर्च (कटी हुई)","1 छोटा लाल प्याज़ (कटा हुआ)","1 बड़ा चम्मच ज़ैतून का तेल","1/8 छोटा चम्मच नमक","16 औंस तिलापिया (4 फ़िलेट [प्रत्येक 4 औंस])","1/2 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच पेपरिका","1 छोटा चम्मच काली मिर्च (या स्वादानुसार)","2 कप अरुगुला (बेबी)","1/2 कप सादा कम वसा वाला ग्रीक योगर्ट","1 बड़ा चम्मच नींबू का रस","1 बड़ा चम्मच ताज़ा सोआ (कटा हुआ)","1 छोटा चम्मच डिजॉन सरसों","1 लहसुन की कली (छोटी, कद्दूकस की हुई)"],
 ["क्विनोआ को धोएँ और पैकेट पर दिए निर्देशों के अनुसार पकाएँ। एक तरफ़ रख दें और गरम रखें।","ओवन को 425 डिग्री F पर पहले से गरम करें। शकरकंद, ज़ुकीनी, शिमला मिर्च और प्याज़ को ज़ैतून के तेल और नमक के साथ मिलाएँ। बेकिंग शीट पर फैलाएँ और 25-30 मिनट भूनें, बीच में एक बार चलाएँ, जब तक कि वे नरम और हल्के कैरामेलाइज़ न हो जाएँ।","ट्राउट फ़िलेट को थपथपाकर सुखा लें और लहसुन पाउडर, पेपरिका और काली मिर्च से मसाला लगाएँ। एक नॉनस्टिक या कच्चे लोहे की कड़ाही को मध्यम आँच पर गरम करें। तिलापिया को त्वचा वाले हिस्से को नीचे रखकर 3-4 मिनट सियर करें, फिर पलटें और 2-3 मिनट और पकाएँ, या जब तक गूदा आसानी से परतों में न बिखरने लगे।","एक छोटे कटोरे में ग्रीक योगर्ट, नींबू का रस, डिजॉन सरसों, सोआ और कद्दूकस किया हुआ लहसुन डालें। चिकना होने और अच्छी तरह मिलने तक फेंटें।","4 कटोरों में से हर एक में क्विनोआ, अरुगुला और भुनी हुई सब्ज़ियों की परत लगाएँ। ऊपर सियर की हुई ट्राउट रखें और परोसने से ठीक पहले दही की चटनी डालें।"]),
("बेक्ड फ़लाफ़ेल",
 "इस रेसिपी में कार्बोहाइड्रेट कम करने के लिए, फ़लाफ़ेल सैंडविच को साबुत गेहूँ के पिटा की जगह सलाद पत्ते के कप में परोसें।",
 "8","1/2 पिटा, 2 फ़लाफ़ेल, 2 बड़े चम्मच सॉस",
 ["1 बड़ा चम्मच लहसुन (बारीक कटा हुआ)","1 छोटा प्याज़ (कटा हुआ)","1 बड़ा चम्मच करी पाउडर","1/4 छोटा चम्मच लाल मिर्च पाउडर (केयेन)","2 बड़े चम्मच हरा धनिया (बारीक कटा हुआ)","1 बड़ा चम्मच अजमोद (बारीक कटा हुआ)","1 बड़ा चम्मच ज़ैतून का तेल","2 डिब्बे, प्रत्येक 15 औंस काबुली चने (छोले) (छानकर और धोकर)","1 1/2 बड़े चम्मच साबुत गेहूँ या मैदा","2 छोटे चम्मच बेकिंग पाउडर","1/2 छोटा चम्मच नमक (वैकल्पिक)","1/2 छोटा चम्मच काली मिर्च","2 स्प्रे, 0.5 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 बड़ा चम्मच तिल","1 कप सादा बिना वसा वाला ग्रीक योगर्ट (नॉन-फ़ैट)","1/4 कप ताहिनी","4 पूरे साबुत गेहूँ के पिटा (आधे कटे हुए)","2 बड़े टमाटर (हर एक के 8 टुकड़े कटे हुए)","1/2 छोटा लाल प्याज़ (पतला कटा हुआ)","2 कप अरुगुला (अच्छी तरह धोया हुआ)"],
 ["ओवन को 450 डिग्री पर पहले से गरम करें। एक बड़ी बेकिंग शीट पर सिलिकॉन मैट या पार्चमेंट पेपर बिछाएँ। अगर पार्चमेंट पेपर इस्तेमाल कर रहे हैं, तो उस पर कुकिंग स्प्रे करें। एक तरफ़ रख दें।","फ़ूड प्रोसेसर या ब्लेंडर में लहसुन, 1 छोटा प्याज़ (कटा हुआ), करी पाउडर, लाल मिर्च पाउडर, हरा धनिया, अजमोद और ज़ैतून का तेल डालें। पीसकर पेस्ट बना लें।","काबुली चने डालें और पल्स करके चनों को कुतर लें और प्याज़ के पेस्ट में मिला दें। चनों का पेस्ट न बनाएँ। फ़लाफ़ेल थोड़ा दरदरा रहना चाहिए।","आटा, बेकिंग पाउडर, नमक (वैकल्पिक) और पिसी काली मिर्च डालें। बस मिलने तक पल्स करें।","फ़लाफ़ेल के मिश्रण को 15-20 मिनट फ़्रिज में रखें। जब तक फ़लाफ़ेल ठंडा हो रहा हो, एक छोटे कटोरे में दही, ताहिनी, लहसुन और अजमोद डालकर फेंट लें। दही की चटनी को इस्तेमाल तक फ़्रिज में रखें।","फ़लाफ़ेल के मिश्रण की लगभग 2 बड़े चम्मच (या 1/8 कप) की गोलियाँ बनाएँ। उन्हें बेकिंग शीट पर रखें और इसी तरह दोहराकर 16 फ़लाफ़ेल गोले बना लें।","फ़लाफ़ेल के गोलों पर कुकिंग स्प्रे करें और तिल छिड़कें।","ओवन की सबसे नीचे वाली रैक पर 15 मिनट बेक करें। ओवन को 350 पर कम करें और बेकिंग शीट को ऊपर वाली रैक पर रखें। 15 मिनट और बेक करें।","फ़लाफ़ेल के बेक हो जाने पर, साबुत गेहूँ के आधे पिटा में दो फ़लाफ़ेल गोले भरें, 2 बड़े चम्मच दही-ताहिनी सॉस, टमाटर के 2 टुकड़े, लाल प्याज़ के 3-4 टुकड़े और 1/4 कप अरुगुला डालें।"]),
("मसले हुए लाल आलू",
 "लाल आलुओं की बनावट मोमी होती है और पकाने पर वे दूसरे आलुओं की तुलना में ज़्यादा सख़्त रहते हैं, जिससे ये सरल मसले हुए आलू थोड़े दरदरे बनते हैं। रंगत और ज़्यादा फ़ाइबर के लिए छिलका रहने दें। अपनी थाली पूरी करें: क्लासिक \"मीट-और-आलू\" भोजन के लिए, इसे साउथवेस्ट-स्टाइल टर्की मीटलोफ़ और संतरे और एवोकाडो वाले सरल हरे सलाद के साथ परोसें।",
 "8","1/2 कप",
 ["2 पाउंड लाल आलू (धोकर 1 इंच के टुकड़ों में कटे हुए)","1/2 कप 1% दूध","1 बड़ा चम्मच मक्खन (बिना नमक वाला)","1/4 छोटा चम्मच नमक","1/8 छोटा चम्मच काली मिर्च"],
 ["स्टीमर बास्केट लगे एक मध्यम बर्तन में 1/4 कप पानी डालें और तेज़ आँच पर उबाल लें। लाल आलू डालें, ढक दें और आँच मध्यम कर दें। आलू नरम होने तक, 25-30 मिनट पकाएँ। ठंडा होने के लिए एक तरफ़ रख दें।","एक छोटे सॉसपैन में दूध और मक्खन को मध्यम आँच पर मक्खन पिघलने तक, 2 मिनट, गरम करें। सॉसपैन को आँच से उतारें और थोड़ा ठंडा होने के लिए एक तरफ़ रख दें।","आलुओं को एक बड़े कटोरे में डालें और आलू मैशर से लगभग चिकना होने तक मसलें। दूध का मिश्रण, नमक और काली मिर्च डालें और अच्छी तरह मिलने तक मिलाएँ।"]),
("मिली-जुली शिमला मिर्च का मेडली",
 "इटली में इस मिश्रण को पेपरोनाटा कहते हैं और यह भुने और ग्रिल किए हुए मांस के साथ परोसी जाने वाली एक आम गार्निश है, लेकिन आप इसे मोरक्कन मसूर विद स्ट्यूड टमाटर जैसे पौधों पर आधारित प्रोटीन के साथ भी परोस सकते हैं, जिससे एक संतोषजनक शाकाहारी (वीगन) भोजन बनता है।",
 "8","1/2 कप",
 ["3 बड़े चम्मच ज़ैतून का तेल","2 पाउंड मिली-जुली लाल, पीली और हरी शिमला मिर्च (पतली पट्टियों में कटी हुई)","6 लहसुन की कलियाँ (बारीक कटी हुई)","1/4 कप गुठली निकाले और कटे हुए हरे ज़ैतून","2 बड़े चम्मच बाल्सेमिक सिरका","1/4 छोटा चम्मच, या स्वादानुसार नमक"],
 ["एक बड़ी, चौड़ी कड़ाही में मध्यम आँच पर ज़ैतून का तेल गरम करें। शिमला मिर्च डालें और भूरी होने तक पकाएँ।","लहसुन डालकर 1 मिनट पकाएँ। हरे ज़ैतून डालें, फिर आँच धीमी करें और ढक दें। 20 मिनट, या शिमला मिर्च के नरम होने तक पकाएँ।","बाल्सेमिक सिरका मिलाएँ। चखकर देखें और ज़रूरत हो तो नमक डालें।"]),
("खीरे के टुकड़े",
 "खीरे के टुकड़ों की पोषण संबंधी जानकारी",
 "1","1/2 कप",
 ["1/2 कप खीरा (टुकड़े)"],[]),
("कुरकुरे ब्रसेल्स स्प्राउट्स",
 "एकदम कुरकुरी, बनाने में आसान यह कुरकुरे ब्रसेल्स स्प्राउट्स रेसिपी मधुमेह के अनुकूल है और बिना स्टार्च वाली सब्ज़ी के साइड डिश के लिए एक बढ़िया विकल्प है।",
 "6","1/2 कप",
 ["1 पाउंड ब्रसेल्स स्प्राउट्स (डंठल हटाकर आधे कटे हुए)","2 बड़े चम्मच ज़ैतून का तेल","1 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच स्मोक्ड पेपरिका","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1 मध्यम नींबू (परोसने के लिए, 6 फाँकों में कटा हुआ)"],
 ["ओवन को 425 डिग्री F पर पहले से गरम करें।","एक बड़े कटोरे में डंठल हटाए और आधे कटे हुए ब्रसेल्स स्प्राउट्स को ज़ैतून का तेल, लहसुन पाउडर, स्मोक्ड पेपरिका, नमक और काली मिर्च के साथ अच्छी तरह लिपटने तक मिलाएँ।","ब्रसेल्स स्प्राउट्स को बेकिंग शीट पर एक परत में फैलाएँ।","पहले से गरम किए ओवन में 20 मिनट या ब्रसेल्स स्प्राउट्स के सुनहरे भूरे और कुरकुरे होने तक भूनें, बीच में पैन को हिला दें।","ब्रसेल्स स्प्राउट्स को ओवन से निकालें और परोसने की डिश में डाल दें।","चाहें तो नींबू की फाँकों के साथ किनारे पर परोसें।"]),
("क्रीमी धनिया चिकन और फूलगोभी स्किलेट",
 "यह स्वादिष्ट बहुत-कम-कार्ब भोजन पैटर्न वाला फूलगोभी स्किलेट आपके परिवार का नया पसंदीदा बन जाएगा। कम कार्ब वाली सब्ज़ियों और प्रोटीन से भरी क्रीमी सॉस बेहतरीन स्वाद और पोषण देती है!",
 "4","2 कप चिकन और सब्ज़ियाँ",
 ["2 बड़े चम्मच ज़ैतून का तेल (बाँटकर)","1 बड़ा चम्मच मैदा","1 कप बिना नमक मिला चिकन ब्रॉथ","1/2 छोटा चम्मच पिसा धनिया","1/4 कप सादा बिना वसा वाला ग्रीक योगर्ट","16 औंस चिकन ब्रेस्ट (छोटे टुकड़ों में कटा हुआ)","4 कप फूलगोभी के फूल","8 औंस क्रेमिनी (बेबी बेला) मशरूम (पतले कटे हुए)","1 बड़ा चम्मच चिली पाउडर","1/4 छोटा चम्मच जीरा","3/4 कप बिना वसा वाली मोज़रेला चीज़ (कसी हुई)","1/4 कप ताज़ा हरा धनिया (कटा हुआ)"],
 ["एक छोटे सॉसपैन को मध्यम-तेज़ आँच पर पहले से गरम करें। पैन गरम होने पर 1 बड़ा चम्मच तेल और मैदा डालें। लगातार फेंटते हुए हल्का सुनहरा होने तक, लगभग 1 मिनट, पकाएँ।","ब्रॉथ और धनिया धीरे-धीरे फेंटते हुए मिलाएँ। उबाल आने दें, फिर आँच कम करें और गाढ़ा होने तक, 2-3 मिनट, पकाएँ। सॉस को आँच से उतारें और दही मिला दें। एक तरफ़ रख दें।","एक ओवन-प्रूफ़ स्किलेट को मध्यम आँच पर पहले से गरम करें। बचा हुआ तेल, चिकन, फूलगोभी, मशरूम और मसाले डालें। बीच-बीच में चलाते हुए पकाएँ, जब तक सब्ज़ियाँ नरम न हो जाएँ और चिकन अंदर तक पक न जाए, 6-7 मिनट।","ओवन को ब्रॉइल पर तेज़ सेट करके पहले से गरम करें। रैक को ओवन के ऊपरी तिहाई हिस्से में रखें।","चिकन पक जाने पर सॉस को स्किलेट में डालें और मिलाने के लिए चलाएँ।","स्किलेट के ऊपर चीज़ डालें और ओवन में रखें। चीज़ के पिघलकर बुलबुले आने तक, 3-5 मिनट, ब्रॉइल करें। हरे धनिये से सजाकर परोसें।"]),
("एज़्टेक टर्की क्विनोआ बर्गर",
 "इन स्वादिष्ट टर्की बर्गरों को भाप में पकी ब्रोकली जैसी बिना स्टार्च वाली सब्ज़ियों के साथ परोसें।",
 "6","1 बर्गर",
 ["1 पाउंड कीमा चिकन (या कम वसा वाला कीमा टर्की)","1/3 कप क्विनोआ (पकी हुई, सुनहरी या लाल)","3 डंठल हरा प्याज़ (स्कैलियन) (बारीक कटा हुआ)","1/2 कप केल (कटी हुई)","1 1/2 बड़े चम्मच एक्स्ट्रा वर्जिन ज़ैतून का तेल","1/2 छोटा चम्मच जीरा","1 छोटा चम्मच सूखा अजवायन (ओरिगैनो)","1 छोटा चम्मच चिली पाउडर","1 पूरी चिपोटले मिर्च एडोबो में (बारीक कटी हुई, वैकल्पिक)"],
 ["एक बड़े कटोरे में सारी सामग्री मिलाएँ और अच्छी तरह मिला लें। 6 पैटी का आकार दें।","ग्रिल को मध्यम-तेज़ आँच पर पहले से गरम करें और बर्गरों को ग्रिल की जाली पर रखें। सीधी आँच पर (ग्रिल बंद रखकर) हर तरफ़ 5-6 मिनट, मनचाहे पकने तक पकाएँ।"]),
("शीट पैन चिकन फ़ाजिटा बाउल",
 "शीट पैन वाला डिनर हफ़्ते के किसी भी दिन के लिए तेज़ और आसान भोजन का बढ़िया विकल्प है, जिसमें सफ़ाई का ज़्यादा झंझट नहीं होता। मेक्सिकन अंदाज़ वाले ये शीट पैन चिकन फ़ाजिटा एक पेट भरने वाला और स्वादिष्ट बाउल बनाते हैं।",
 "4","6 औंस चिकन + 1 कप सब्ज़ी और बीन्स का मिश्रण",
 ["2 छोटे चम्मच चिली पाउडर","2 छोटे चम्मच पिसा जीरा","1/4 छोटा चम्मच कोशर नमक","1/2 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच स्मोक्ड पेपरिका","1/4 छोटा चम्मच काली मिर्च","2 बड़े चम्मच कैनोला तेल (बाँटकर)","1 1/2 पाउंड बिना हड्डी और बिना त्वचा वाले चिकन ब्रेस्ट (1 इंच के टुकड़ों में कटे हुए)","1 बड़ा पीला प्याज़ (कटा हुआ)","1 पूरी लाल शिमला मिर्च (कटी हुई)","1 पूरी हरी शिमला मिर्च (कटी हुई)","1 (15 औंस) डिब्बा काली बीन्स (कम सोडियम, छानकर और धोकर)","1/4 कप सादा बिना वसा वाला ग्रीक योगर्ट","1 बड़ा चम्मच लाइम का रस","1 छोटा चम्मच हॉट सॉस","1 रोमेन लेट्यूस का गुच्छा (कटा हुआ)"],
 ["ओवन को 425 डिग्री F पर गरम करें और शीट पैन पर पार्चमेंट पेपर बिछाएँ।","एक बड़े कटोरे में चिली पाउडर, जीरा, कोशर नमक, लहसुन पाउडर, पेपरिका और पिसी काली मिर्च मिलाएँ। 1 बड़ा चम्मच तेल डालकर फेंटें। चिकन, प्याज़ और लाल व हरी शिमला मिर्च डालें और अच्छी तरह लपेटने के लिए मिलाएँ।","चिकन और सब्ज़ियों को शीट पैन पर एक परत में फैलाएँ। 15 मिनट बेक करें।","एक बड़े कटोरे में काली बीन्स और बचा हुआ 1 बड़ा चम्मच ज़ैतून का तेल मिलाएँ।","पैन को ओवन से निकालें और चिकन व सब्ज़ियों को चलाएँ। ऊपर से बीन्स बराबर फैला दें। चिकन के 165 डिग्री F तक पहुँचने और सब्ज़ियों के नरम होने तक, 5-7 मिनट और भूनें।","एक छोटे कटोरे में दही, लाइम का रस और हॉट सॉस मिलाएँ।","लेट्यूस, चिकन, बीन्स और सब्ज़ियों को चार कटोरों में बाँट दें। ऊपर से दही की चटनी डालें और अतिरिक्त हॉट सॉस या सालसा के साथ परोसें।"]),
]
